def _determine_ina_placement_candidates(self):
    # Step 1: Initialize traffic load per switch
    switch_traffic_load = {s: 0.0 for s in self.ina_candidates}

    # Step 2: For each job, compute traffic from every worker to its PS, and accumulate on each switch in the path
    for j in range(self.jobs_num):
        job_size = self.jobs_size[j]
        workers = self.workers_id[j]
        ps_node = self.ps_id[j]
        sd_node = self.sd_id[j]

        # For each worker in the job
        for w in workers:
            # Get the shortest path from worker to PS
            path = self._get_path_links(w, ps_node)

            # Add job_size to every switch in the path (except the PS)
            for u, v in path:
                if v != ps_node:  # Avoid adding to PS itself
                    if v in switch_traffic_load:
                        switch_traffic_load[v] += job_size
                # Also add to the ToR switch (sd_node) if not already counted
                if u == w and v == sd_node and v in switch_traffic_load:
                    switch_traffic_load[v] += job_size

    # Step 3: Compute Pod-wise average load for each Pod
    pod_traffic = {}
    pod_switches = {}

    for s in self.ina_candidates:
        pod_id = self._get_node_pod(s)
        if pod_id not in pod_traffic:
            pod_traffic[pod_id] = 0.0
            pod_switches[pod_id] = 0
        pod_traffic[pod_id] += switch_traffic_load[s]
        pod_switches[pod_id] += 1

    # Compute average load per switch per Pod
    pod_avg_load = {}
    for pod_id in pod_traffic:
        pod_avg_load[pod_id] = pod_traffic[pod_id] / pod_switches[pod_id] if pod_switches[pod_id] > 0 else 0.0

    # Step 4: Assign composite score to each switch
    # Score = (total traffic) * (1 - normalized imbalance) * (proximity weight)
    # Proximity: ToR (1.0), Aggr (0.8), Core (0.6)
    switch_scores = {}

    for s in self.ina_candidates:
        pod_id = self._get_node_pod(s)
        total_load = switch_traffic_load[s]
        avg_load = pod_avg_load.get(pod_id, 0.0)

        # Imbalance penalty: if load is far from average, lower score
        if avg_load == 0.0:
            imbalance = 1.0
        else:
            imbalance = min(total_load / avg_load, avg_load / total_load)

        # Proximity weight: ToR > Aggr > Core
        weight = 1.0
        if s in self.tors_id:
            weight = 1.0
        elif s in self.aggrs_id:
            weight = 0.8
        elif s in self.cores_id:
            weight = 0.6

        # Composite score
        score = total_load * imbalance * weight
        switch_scores[s] = score

    # Step 5: Sort switches by score in descending order
    sorted_switches = sorted(switch_scores.keys(), key=lambda s: switch_scores[s], reverse=True)

    # Step 6: Select top B_INA switches, ensuring load balancing across Pods
    selected_switches = []
    selected_pods = set()

    for s in sorted_switches:
        if len(selected_switches) >= self.ina_budget:
            break
        pod_id = self._get_node_pod(s)
        # Avoid over-representing any Pod
        if pod_id in selected_pods and len([x for x in selected_switches if self._get_node_pod(x) == pod_id]) >= 2:
            continue
        selected_switches.append(s)
        selected_pods.add(pod_id)

    # Ensure at least one switch per Pod if possible, but stay within budget
    # If any Pod is missing, add the highest-scoring switch from that Pod
    all_pods = set(self._get_node_pod(s) for s in self.ina_candidates)
    missing_pods = all_pods - selected_pods

    for pod_id in missing_pods:
        if len(selected_switches) >= self.ina_budget:
            break
        # Find highest-scoring switch in this Pod
        pod_switches = [s for s in self.ina_candidates if self._get_node_pod(s) == pod_id]
        if pod_switches:
            best_s = max(pod_switches, key=lambda s: switch_scores[s])
            if best_s not in selected_switches:
                selected_switches.append(best_s)

    # Final trim to budget
    selected_switches = selected_switches[:self.ina_budget]

    # Step 7: Store result
    self._ina_placement_candidates = sorted(selected_switches, key=lambda s: switch_scores[s], reverse=True)
